def load() -> pd.DataFrame:
    import pandas as pd

    path = 'data/legal/input/metropolitan_statistics.html'
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        html = f.read()

    # Avoid pandas.read_html (may require optional deps like html5lib).
    # Use BeautifulSoup to extract tables and parse them with pd.read_html on a per-table basis,
    # which works with the built-in lxml parser in this environment.
    from bs4 import BeautifulSoup

    soup = BeautifulSoup(html, 'lxml')
    tables = soup.find_all('table')
    if not tables:
        return pd.DataFrame({'tableIndex': [], 'note': []})

    out = []
    for i, tbl in enumerate(tables):
        tbl_html = str(tbl)
        # Use lxml (default) parser; should not require html5lib.
        try:
            parsed = pd.read_html(tbl_html)[0]
        except Exception:
            # If a table can't be parsed, skip it.
            continue
        parsed.columns = [str(c) for c in parsed.columns]
        parsed.insert(0, 'tableIndex', i)
        out.append(parsed)

    if not out:
        return pd.DataFrame({'tableIndex': [], 'note': ['no parseable tables']})

    return pd.concat(out, ignore_index=True, sort=False)

def load() -> pd.DataFrame:
    import pandas as pd
    import glob
    import os

    pattern = 'data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*'
    paths = sorted(glob.glob(pattern))
    if not paths:
        raise FileNotFoundError(f'No files matched pattern: {pattern}')

    dfs = []
    for p in paths:
        ext = os.path.splitext(p)[1].lower()
        if ext in ['.csv', '.txt']:
            df = pd.read_csv(p, dtype=str)
        elif ext in ['.xlsx', '.xls']:
            df = pd.read_excel(p, dtype=str)
        else:
            # Try csv as fallback
            df = pd.read_csv(p, dtype=str)
        df.insert(0, 'sourceFile', os.path.basename(p))
        dfs.append(df)

    return pd.concat(dfs, ignore_index=True, sort=False)

def process(metroStatsHtml) -> pd.DataFrame:
    import pandas as pd
    import re

    df = metroStatsHtml.copy()

    # Use the table with columns: Metropolitan statistical area, 2024 estimate, 2020 census
    needed = {'Metropolitan statistical area', '2024 estimate', '2020 census'}
    have = needed.issubset(set(df.columns))
    if not have:
        # Return empty but with expected schema
        return pd.DataFrame(columns=['metroRawHtml', 'pop2020', 'pop2024', 'pop2023'])

    sub = df.loc[df['Metropolitan statistical area'].notna(), ['Metropolitan statistical area', '2024 estimate', '2020 census']].copy()
    sub = sub.rename(columns={'Metropolitan statistical area': 'metroRawHtml', '2024 estimate': 'pop2024', '2020 census': 'pop2020'})

    # Coerce numeric
    for c in ['pop2020', 'pop2024']:
        sub[c] = pd.to_numeric(sub[c], errors='coerce')

    sub = sub.dropna(subset=['pop2020', 'pop2024', 'metroRawHtml'])

    # Linear interpolation for 2023 between 2020 and 2024 (3/4 of the way)
    sub['pop2023'] = sub['pop2020'] + (sub['pop2024'] - sub['pop2020']) * (3.0/4.0)

    return sub.reset_index(drop=True)

def process(metroNameKey) -> pd.DataFrame:
    import pandas as pd

    df = metroNameKey.copy()
    if 'avgIdentityTheftReports' not in df.columns or df.empty:
        return pd.DataFrame([{'value': None}])

    val = float(df.loc[df.index[0], 'avgIdentityTheftReports'])
    return pd.DataFrame([{'value': round(val, 4)}])
